// The Webhook's JWT Auth checked this token against Landbright's JWKS: trust jwtPayload, not the body.
const e = $json.jwtPayload.event;
const kind = e.data.kind ?? e.data.identity?.kind ?? e.identity?.kind ?? 'person';
const fields = Array.isArray(e.data.fields) ? e.data.fields : [];
return {
  type: e.type,
  personId: e.target.id,
  kind,
  joiner: e.type === 'identity.created' && kind === 'person',
  // A mover: their department changed (from HR through the upsert, or in the console).
  mover: e.type === 'identity.updated' && fields.includes('department'),
};

parameters.code:
// Birthright groups: everyone gets the first list; a department adds its own. Edit the map here (the one place: joiners
// and movers both come through it); groups that don't exist in Landbright are skipped and reported as missing (create
// them there, kind "birthright").
const EVERYONE = ['Everyone'];
const BY_DEPARTMENT = {
  Engineering: ['Engineers', 'Landflow Editors'],
  Finance: ['Finance'],
  Security: ['Security'],
};
const p = $input.first().json;
const names = [...new Set([...EVERYONE, ...(BY_DEPARTMENT[p.department] ?? [])])];
return [{ groups: names }];

parameters.codeEach:
const p = $json;
const groups = (p.groups ?? []).map((g) => g.name);
return {
  to: p.email,
  toName: p.displayName,
  subject: `Welcome${p.department ? ` to ${p.department}` : ''}, ${p.givenName}`,
  text: [
    `Hi ${p.givenName},`,
    '',
    `You're set up in Landbright${groups.length ? `, in ${groups.join(', ')}` : ''}.`,
    p.status === 'pre_hire' ? `Your invite email, with the link to choose a password, comes on your start date (${p.startDate}). At your first sign-in you will also set up a second step` : 'Your invite email has the link to choose a password. At your first sign-in you will also set up a second step',
    '(an authenticator app or a passkey) and accept the terms.',
    '',
    'Need more access for a while? Ask in Landbright: Access → Ask for access.',
  ].join('\n'),
};
